-- Repair (idempotent): 与 V33 等价。当库中缺少 fdc_country_region_t（Flyway 记录与实库不一致、或表被误删）时补建并灌入行政区划数据；已存在则跳过冲突行。
-- China country/province/city region data from .docs/china_regions.md
CREATE TABLE IF NOT EXISTS fdc_country_region_t (
    region_id BIGSERIAL PRIMARY KEY,
    iso_alpha2 VARCHAR(2) NOT NULL,
    iso_alpha3 VARCHAR(3) NOT NULL,
    iso_numeric VARCHAR(3) NOT NULL,
    country_name_zh VARCHAR(64) NOT NULL,
    country_name_en VARCHAR(128) NOT NULL,
    region_level VARCHAR(16) NOT NULL,
    region_code VARCHAR(12) NOT NULL,
    region_name VARCHAR(128) NOT NULL,
    short_name VARCHAR(64),
    parent_region_code VARCHAR(12),
    sort_order INTEGER NOT NULL DEFAULT 1,
    enable_flag VARCHAR(1) NOT NULL DEFAULT 'Y',
    delete_flag VARCHAR(1) NOT NULL DEFAULT 'N',
    created_by BIGINT NOT NULL DEFAULT 1,
    creation_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_updated_by BIGINT NOT NULL DEFAULT 1,
    last_update_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    tenantid BIGINT NOT NULL DEFAULT 1,
    CONSTRAINT ck_fdc_country_region_level CHECK (region_level IN ('COUNTRY', 'PROVINCE', 'CITY')),
    CONSTRAINT ck_fdc_country_region_enable CHECK (enable_flag IN ('Y', 'N')),
    CONSTRAINT ck_fdc_country_region_delete CHECK (delete_flag IN ('Y', 'N'))
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_fdc_country_region_code_active
    ON fdc_country_region_t (region_code)
    WHERE delete_flag = 'N';

CREATE INDEX IF NOT EXISTS idx_fdc_country_region_parent_active
    ON fdc_country_region_t (parent_region_code)
    WHERE delete_flag = 'N';

